import React, {Component, useState} from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from 'axios';

function Order(){
    const [values, setValues] = useState({
        name: '',
        position: '',
        room: '',
        email: '',
        note: '',
        pwd: '',
    });

    const [count, setCount] = useState(0);

    const navigate = useNavigate();
    // send cookie with http request
    axios.defaults.withCredentials = true;

    const handleReset = () => {
        setValues({
          name: '',
          position: '',
          room: '',
          email: '',
          note: '',
          pwd: '',
        });
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        console.log("Data send is:");
        console.log(values);

        // your emailjs service ID, template ID and Public Key
        // const serviceId = 'service_zs5ns18';
        // const templateId = 'template_uunf4ci';
        // const publicKey = '1IUziC0tRlXWE7iB6';

        if (values.name === '' || values.position === '' || values.room === '' || values.email === '' || values.note === '' || values.pwd === ''){
            alert("Gửi email lỗi! Hãy nhập đầy đủ thông tin");
        }
        else{
            console.log("Send email request");
            // axios.post('http://localhost:8081/order', values)
            // .then(res => {
            //     if(res.data.Status === "Success") {
            //         // navigate('/map')
            //         console.log("Send email successfully");
            //     }

            //     else{
            //         alert(res.data.Error);
            //     }
            //     console.log(res)
            // })

            // .then(err => console.log(err));

            //create a new object that contains dynamic template params
            // const templateParams = {
            //     from_name: values.email,
            //     to_name: values.name,
            //     to_position: values.position,
            //     to_room: values.room,
            //     to_note: values.note,
            //     to_pwd: values.pwd
            // };
        }
    }

    const handleAdd = () => {
        setCount(count + 1);
        console.log("Nút add được nhấn", count);

        // reset form for add new data

    }

    return(
        <div className="d-flex justify-content-center align-items-center no-bg vh-1">
            <div className=" bg-white p-3 rounded w-100">
                <h2>Order</h2>

                <form onSubmit={handleSubmit}>
                    <div className="mb-3">
                        <label htmlFor="name"><strong>Document Name</strong></label>
                        <input type="text" placeholder="Enter Document Name" name="name" 
                        onChange={e => setValues({...values, name: e.target.value})} className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="name"><strong>Position</strong></label>
                        <input type="text" placeholder="Enter position of locker" name="position" 
                        onChange={e => setValues({...values, position: e.target.value})} className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="name"><strong>Room</strong></label>
                        <input type="text" placeholder="Enter room number" name="room" 
                        onChange={e => setValues({...values, room: e.target.value})} className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="email"><strong>Email</strong></label>
                        <input type="text" placeholder="Enter Email" name="email" 
                        onChange={e => setValues({...values, email: e.target.value})} className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="email"><strong>Note</strong></label>
                        <input type="text" placeholder="Enter description" name="note" 
                        onChange={e => setValues({...values, note: e.target.value})} className="form-control rounded-0"/>
                    </div>

                    <div className="mb-3">
                        <label htmlFor="password"><strong>Password</strong></label>
                        <input type="text" placeholder="Enter Password" name="pwd" 
                        onChange={e => setValues({...values, pwd: e.target.value})} className="form-control rounded-0"/>
                    </div>

                    <div>
                        <button className="btn btn-success w-50 rounded-0" style={{ border: '5px solid white', padding: '10px 20px', borderRadius: '5px' }} onClick={handleAdd}>Add</button>
                        <button type="submit" className="btn btn-success w-50 rounded-0" style={{ border: '5px solid white', padding: '10px 20px', borderRadius: '5px' }}>Submit</button>
                    </div>
                </form>
            </div>
        </div>
    )
}

export default Order;
